export interface FieldScanCandidate {
  fieldId: string;
  selectorHint: string;
  label: string;
  elementTag: FieldElementTag;
  inputType: string;
  name: string;
  elementId: string;
  placeholder: string;
  ariaLabel: string;
  autocomplete: string;
  sectionHeading: string;
  nearbyText: string;
  optionLabels: string[];
  adapterSignals: string[];
  required: boolean;
}

export interface ResolvedProfileValue {
  raw: string | string[] | null;
  preview: string;
  hasValue: boolean;
}

interface FieldDefinition {
  key: ProfileFieldKey;
  label: string;
  synonyms: string[];
  autocomplete?: string[];
  preferredTags?: FieldElementTag[];
  preferredInputTypes?: string[];
  disallowedInputTypes?: string[];
  getValue: (
    profile: ApplicantProfile,
    entryIndex?: number
  ) => ResolvedProfileValue;
}

interface FieldEvaluation {
  key: ProfileFieldKey;
  label: string;
  score: number;
  signals: string[];
  valuePreview: string;
  hasValue: boolean;
}

